import{x as d,o as e,c as o,a9 as r}from"./chunks/framework.DxG24V0C.js";const a="/agentsrc/images/claudecode/article-index-architecture.svg",g=JSON.parse('{"title":"Claude Code 源码精读","description":"","frontmatter":{"title":"Claude Code 源码精读"},"headers":[],"relativePath":"claudecode/index.md","filePath":"claudecode/index.md","lastUpdated":1787409644000}'),c={name:"claudecode/index.md"};function n(s,t,l,i,h,m){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="claude-code-源码精读" tabindex="-1">Claude Code 源码精读 <a class="header-anchor" href="#claude-code-源码精读" aria-label="Permalink to &quot;Claude Code 源码精读&quot;">​</a></h1><blockquote><p>Anthropic 官方终端编程 Agent 源码深度解析</p></blockquote><p>这里是「<strong>Claude Code 源码精读</strong>」专栏，基于泄漏源码分析 Claude Code 的架构设计与核心机制。</p><p>Claude Code 是 Anthropic 官方出品的终端 AI 编程助手，用 TypeScript 编写、Bun 运行时驱动。其源码规模约 <strong>51 万行</strong>、~1,900 个文件，是当前最成熟的终端编程 Agent 之一。</p><p>本系列从源码组织结构出发，逐层拆解其核心模块的设计思路与实现细节。</p><h2 id="文章列表" tabindex="-1">文章列表 <a class="header-anchor" href="#文章列表" aria-label="Permalink to &quot;文章列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>文章</th><th>主题</th><th>字数</th></tr></thead><tbody><tr><td>1</td><td><a href="/agentsrc/claudecode/01-overview.html">整体架构与启动流程</a></td><td>51 万行源码全景、Bun 运行时、React + Ink 终端 UI、分层架构</td><td></td></tr><tr><td>2</td><td><a href="/agentsrc/claudecode/02-mainloop.html">主循环：QueryEngine 与 Continuation-Driven 架构</a></td><td>流式 API 调用循环、工具调度、continuation-based turn 管理</td><td></td></tr><tr><td>3</td><td><a href="/agentsrc/claudecode/03-tools.html">工具系统：40+ 内置工具</a></td><td>Tool 接口设计、20+ 工具目录、MCP 扩展</td><td></td></tr><tr><td>4</td><td><a href="/agentsrc/claudecode/04-compact.html">对话压缩：5 级压缩机制</a></td><td>autoCompact / microCompact / apiMicrocompact / reactiveCompact / sessionMemoryCompact</td><td></td></tr><tr><td>5</td><td><a href="/agentsrc/claudecode/05-agents.html">Agent 系统：单 Agent 调度与 Swarm 协作</a></td><td>AgentTool、Coordinator、Teammate 模式、Agent Swarms</td><td></td></tr><tr><td>6</td><td><a href="/agentsrc/claudecode/06-commands.html">命令系统：70+ 斜杠命令与 CLI 参数</a></td><td>Commander.js 解析、commit/review/mcp/memory 等命令实现</td><td></td></tr><tr><td>7</td><td><a href="/agentsrc/claudecode/07-permissions.html">权限系统：7 种权限模式</a></td><td>5 外部 + 2 内部权限模式、AI 分类器、denial tracking</td><td></td></tr><tr><td>8</td><td><a href="/agentsrc/claudecode/08-mcp.html">MCP 集成架构</a></td><td>4 种传输层、OAuth 认证、官方注册表、插件系统</td><td></td></tr><tr><td>9</td><td><a href="/agentsrc/claudecode/09-bridge.html">Bridge 桥接与远程模式</a></td><td>IDE 扩展通信、JSON-RPC over WebSocket、Remote Session、SDK 适配层</td><td></td></tr><tr><td>10</td><td><a href="/agentsrc/claudecode/10-memory.html">记忆系统与上下文注入</a></td><td>claude.md、memdir 持久化、SessionMemory、MagicDocs、AutoDream</td><td></td></tr></tbody></table><h2 id="关于本系列" tabindex="-1">关于本系列 <a class="header-anchor" href="#关于本系列" aria-label="Permalink to &quot;关于本系列&quot;">​</a></h2><p>本系列基于 Claude Code 泄漏源码分析，源码引用详见 <code>agent/claude-code-main/</code> 目录。</p><h3 id="核心分析路径" tabindex="-1">核心分析路径 <a class="header-anchor" href="#核心分析路径" aria-label="Permalink to &quot;核心分析路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>对应目录</th><th>规模</th></tr></thead><tbody><tr><td><strong>入口与引导</strong></td><td><code>src/main.tsx</code></td><td>4,683 行</td></tr><tr><td><strong>主循环</strong></td><td><code>src/QueryEngine.ts</code> + <code>src/query.ts</code></td><td>~3K 行</td></tr><tr><td><strong>工具系统</strong></td><td><code>src/tools/</code> (43 子目录) + <code>src/Tool.ts</code></td><td>~800 行接口 + ~40 工具</td></tr><tr><td><strong>命令系统</strong></td><td><code>src/commands/</code> (~40 目录) + <code>src/commands.ts</code></td><td>~750 行注册 + 50 命令</td></tr><tr><td><strong>状态管理</strong></td><td><code>src/state/</code></td><td>6 文件</td></tr><tr><td><strong>服务层</strong></td><td><code>src/services/</code> (36 目录)</td><td>包括 API / MCP / LSP / Compact 等</td></tr><tr><td><strong>Hook 层</strong></td><td><code>src/hooks/</code> (85 文件)</td><td>React Hook 驱动的业务逻辑</td></tr><tr><td><strong>UI 层</strong></td><td><code>src/screens/</code> + <code>src/components/</code></td><td>React + Ink 终端组件</td></tr><tr><td><strong>IDE 桥接</strong></td><td><code>src/bridge/</code> (31 文件)</td><td>JSON-RPC over WebSocket</td></tr><tr><td><strong>记忆系统</strong></td><td><code>src/memdir/</code></td><td>跨会话持久化</td></tr><tr><td><strong>任务系统</strong></td><td><code>src/tasks/</code> (7 文件)</td><td>4 种后台任务类型</td></tr></tbody></table><h3 id="特色" tabindex="-1">特色 <a class="header-anchor" href="#特色" aria-label="Permalink to &quot;特色&quot;">​</a></h3><ul><li>每篇文章附带与其他框架（OpenCode / Codex）的架构对比</li><li>基于真实源码的逐行走读</li><li>以架构图 + 流程图为辅助理解工具</li></ul><h2 id="架构速览" tabindex="-1">架构速览 <a class="header-anchor" href="#架构速览" aria-label="Permalink to &quot;架构速览&quot;">​</a></h2><p><img src="'+a+'" alt="Claude Code 主循环：QueryEngine 流式调用，分流渲染 / 工具执行 / 完成"></p>',15)])])}const p=d(c,[["render",n]]);export{g as __pageData,p as default};
